package main

import (
	"fmt"
	"slices"
	"time"
)

func percentile(times []time.Duration, p int) time.Duration {
	slices.Sort(times)
	return times[len(times)*p/100]
}

func main() {
	times := make([]time.Duration, 0, 2000)
	for i := 1; i <= 2000; i++ {
		times = append(times, time.Duration(i)*time.Microsecond)
	}
	fmt.Println("p99 =", percentile(times, 99))
	fmt.Println("max =", percentile(times, 100))
}
